    #[test]
    fn build_report_scrubs_command() {
        let mut env = HashMap::new();
        env.insert("DB_PASSWORD".to_string(), "secret123".to_string());

        let report = build_report(
            "db",
            "psql -p secret123 mydb",
            Some(1),
            "connection refused",
            "retry",
            &env,
        );

        assert!(!report.command_scrubbed.contains("secret123"));
    }

    #[test]
    fn build_report_with_no_exit_code() {
        let report = build_report(
            "test",
            "echo hi",
            None,
            "killed by signal",
            "shell",
            &HashMap::new(),
        );

        assert_eq!(report.exit_code, None);
    }

    #[test]
    fn build_report_platform_format() {
        let report = build_report(
            "test",
            "echo",
            Some(0),
            "",
            "retry",
            &HashMap::new(),
        );

        // Platform should be "os-arch" format
        assert!(report.platform.contains('-'));
        let parts: Vec<&str> = report.platform.split('-').collect();
        assert_eq!(parts.len(), 2);
    }

    #[test]
    fn build_report_version_is_cargo_version() {
        let report = build_report(
            "test",
            "echo",
            Some(0),
            "",
            "retry",
            &HashMap::new(),
        );

        assert_eq!(report.bivvy_version, env!("CARGO_PKG_VERSION"));
    }

    #[test]
    fn failure_report_serializes_to_yaml() {
        let report = build_report(
            "bundler",
            "bundle install",
            Some(1),
            "gem not found",
            "retry",
            &HashMap::new(),
        );

        let yaml = serde_yaml::to_string(&report).unwrap();
        assert!(yaml.contains("step_name: bundler"));
        assert!(yaml.contains("command_scrubbed: bundle install"));
        assert!(yaml.contains("exit_code: 1"));
        assert!(yaml.contains("error_scrubbed: gem not found"));
        assert!(yaml.contains("recovery_action: retry"));
    }

    #[test]
    fn failure_report_deserializes_from_yaml() {
        let report = build_report(
            "cargo",
            "cargo build",
            Some(101),
            "compile error",
            "fix",
            &HashMap::new(),
        );

        let yaml = serde_yaml::to_string(&report).unwrap();
        let deserialized: FailureReport = serde_yaml::from_str(&yaml).unwrap();

        assert_eq!(deserialized.step_name, "cargo");
        assert_eq!(deserialized.command_scrubbed, "cargo build");
        assert_eq!(deserialized.exit_code, Some(101));
        assert_eq!(deserialized.error_scrubbed, "compile error");
        assert_eq!(deserialized.recovery_action, "fix");
    }

    #[test]
    fn failure_report_roundtrip_with_none_exit_code() {
        let report = build_report("test", "cmd", None, "err", "retry", &HashMap::new());

        let yaml = serde_yaml::to_string(&report).unwrap();
        let deserialized: FailureReport = serde_yaml::from_str(&yaml).unwrap();

        assert_eq!(deserialized.exit_code, None);
    }

    #[test]
    fn telemetry_consent_display() {
        assert_eq!(TelemetryConsent::Send.to_string(), "send");
        assert_eq!(TelemetryConsent::NoThanks.to_string(), "no_thanks");
        assert_eq!(TelemetryConsent::Always.to_string(), "always");
        assert_eq!(TelemetryConsent::Never.to_string(), "never");
    }

    #[test]
    fn telemetry_prompt_returns_always() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "always");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Always);
    }

    #[test]
    fn telemetry_prompt_returns_never() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
