        ui.set_prompt_response("telemetry_failure", "never");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::Never);
    }

    #[test]
    fn telemetry_prompt_unknown_response_defaults_to_no_thanks() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "banana");

        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(result, TelemetryConsent::NoThanks);
    }

    #[test]
    fn telemetry_prompt_shows_step_name_in_messages() {
        let report = build_report(
            "my_step",
            "my_command",
            Some(42),
            "error text here",
            "shell → retry",
            &HashMap::new(),
        );
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        assert!(ui.has_message("my_step"));
        assert!(ui.has_message("my_command"));
        assert!(ui.has_message("42"));
        assert!(ui.has_message("error text here"));
        assert!(ui.has_message("shell → retry"));
    }

    #[test]
    fn telemetry_prompt_hides_exit_code_when_none() {
        let report = build_report("test", "cmd", None, "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        // Should not contain "Exit:" line
        assert!(!ui.messages().iter().any(|m| m.contains("Exit:")));
    }

    #[test]
    fn telemetry_prompt_hides_error_when_empty() {
        let report = build_report("test", "cmd", Some(1), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        assert!(!ui.messages().iter().any(|m| m.contains("Error:")));
    }

    #[test]
    fn telemetry_prompt_saved_pref_unknown_still_prompts() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "send");

        let result = prompt_telemetry(&mut ui, &report, Some("garbage")).unwrap();
        assert_eq!(result, TelemetryConsent::Send);
        assert!(!ui.prompts_shown().is_empty());
    }

    #[test]
    fn telemetry_prompt_no_saved_pref_prompts() {
        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "send");

        prompt_telemetry(&mut ui, &report, None).unwrap();
        assert_eq!(ui.prompts_shown(), &["telemetry_failure"]);
    }

    #[test]
    fn save_report_creates_directory_and_file() {
        let temp = tempfile::TempDir::new().unwrap();
        let sub = temp.path().join("nested").join("reports");
        let report = build_report("test", "cmd", Some(0), "err", "retry", &HashMap::new());

        let path = save_report_to(&report, &sub).unwrap();
        assert!(path.exists());
        assert!(sub.exists());
    }

    #[test]
    fn save_report_filename_contains_step_name() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report("my_step", "cmd", Some(0), "", "retry", &HashMap::new());

        let path = save_report_to(&report, temp.path()).unwrap();
        let filename = path.file_name().unwrap().to_str().unwrap();
        assert!(filename.contains("my_step"));
        assert!(filename.ends_with(".yml"));
    }

    #[test]
    fn save_report_content_is_valid_yaml() {
        let temp = tempfile::TempDir::new().unwrap();
        let report = build_report(
            "bundler",
            "bundle install",
            Some(1),
            "error msg",
            "retry",
            &HashMap::new(),
        );

        let path = save_report_to(&report, temp.path()).unwrap();
        let content = std::fs::read_to_string(&path).unwrap();
        let parsed: FailureReport = serde_yaml::from_str(&content).unwrap();

        assert_eq!(parsed.step_name, "bundler");
        assert_eq!(parsed.command_scrubbed, "bundle install");
        assert_eq!(parsed.exit_code, Some(1));
        assert_eq!(parsed.error_scrubbed, "error msg");
        assert_eq!(parsed.recovery_action, "retry");
    }

    #[test]
    fn save_multiple_reports_creates_separate_files() {
        let temp = tempfile::TempDir::new().unwrap();
        let report1 = build_report("step1", "cmd1", Some(0), "", "retry", &HashMap::new());
        let report2 = build_report("step2", "cmd2", Some(1), "", "fix", &HashMap::new());

        let path1 = save_report_to(&report1, temp.path()).unwrap();
        let path2 = save_report_to(&report2, temp.path()).unwrap();

        assert_ne!(path1, path2);
        assert!(path1.exists());
        assert!(path2.exists());
    }

    #[test]
    fn reports_dir_ends_with_expected_path() {
        let dir = reports_dir();
        assert!(dir.ends_with(".bivvy/failure-reports"));
    }
}

