        );
    }

    #[test]
    fn scrub_removes_filesystem_paths() {
        let input = "Error: file not found at /Users/brenna/project/src/main.rs";
        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
        assert!(
            scrubbed.contains("[PATH]"),
