        let scrubbed = scrub_for_telemetry(&long_input, &HashMap::new());
        assert!(scrubbed.len() <= MAX_ERROR_LENGTH + 20); // +20 for the truncation message
        assert!(scrubbed.ends_with("...[truncated]"));
    }

