        assert_eq!(report.exit_code, Some(1));
        assert_eq!(report.error_scrubbed, "gem build error");
        assert_eq!(report.recovery_action, "retry");
        assert!(!report.bivvy_version.is_empty());
        assert!(!report.platform.is_empty());
    }

