            "my_step",
            "my_command",
            Some(42),
            "error text here",
            "shell → retry",
            &HashMap::new(),
        );
        let mut ui = crate::ui::MockUI::new();
        ui.set_interactive(true);
        ui.set_prompt_response("telemetry_failure", "no_thanks");

        prompt_telemetry(&mut ui, &report, None).unwrap();

        assert!(ui.has_message("my_step"));
        assert!(ui.has_message("my_command"));
        assert!(ui.has_message("42"));
        assert!(ui.has_message("error text here"));
        assert!(ui.has_message("shell → retry"));
    }

    #[test]
    fn telemetry_prompt_hides_exit_code_when_none() {
